-- Phase 3A: collector vocabulary, the registry rule for BLOCKED collectors,
-- and scope authorisations. Generated by drizzle-kit, then hand-edited where
-- marked. Row-level security and grants for the new table are in 0008.
--
-- collection_mode keeps its Phase 2A value PASSIVE: Postgres cannot drop an
-- enum value in place and rows written then hold it. Application code can no
-- longer write it.
CREATE TYPE "public"."target_type" AS ENUM('DOMAIN', 'IP_ADDRESS', 'EMAIL_ADDRESS', 'PHONE_NUMBER', 'USERNAME', 'ORGANIZATION', 'URL', 'FILE');--> statement-breakpoint
ALTER TYPE "public"."collection_mode" ADD VALUE 'PASSIVE_API' BEFORE 'ACTIVE';--> statement-breakpoint
ALTER TYPE "public"."collection_mode" ADD VALUE 'PASSIVE_DATASET' BEFORE 'ACTIVE';--> statement-breakpoint
ALTER TYPE "public"."collection_mode" ADD VALUE 'PASSIVE_PUBLIC_WEB' BEFORE 'ACTIVE';--> statement-breakpoint
ALTER TYPE "public"."collection_mode" ADD VALUE 'LOCAL_ANALYSIS' BEFORE 'ACTIVE';--> statement-breakpoint
CREATE TABLE "scope_authorisations" (
	"tenant_id" uuid NOT NULL,
	"id" uuid DEFAULT gen_random_uuid() NOT NULL,
	"target_type" "target_type" NOT NULL,
	"target" text NOT NULL,
	"authorised_by_user_id" uuid NOT NULL,
	"basis" text NOT NULL,
	"valid_from" timestamp with time zone NOT NULL,
	"valid_until" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "scope_authorisations_pk" PRIMARY KEY("tenant_id","id"),
	CONSTRAINT "scope_authorisations_target_not_blank" CHECK (length(btrim("scope_authorisations"."target")) > 0),
	CONSTRAINT "scope_authorisations_basis_not_blank" CHECK (length(btrim("scope_authorisations"."basis")) > 0),
	CONSTRAINT "scope_authorisations_period" CHECK ("scope_authorisations"."valid_until" > "scope_authorisations"."valid_from")
);
--> statement-breakpoint
ALTER TABLE "collectors_registry" DROP CONSTRAINT "collectors_registry_enabled_requires_permitted";--> statement-breakpoint
-- Hand-edited: drizzle-kit recreated the type through text, which would fail
-- on any existing NOT_PERMITTED row. Renaming keeps every row valid and
-- rewrites nothing.
ALTER TYPE "public"."commercial_use_verdict" RENAME VALUE 'NOT_PERMITTED' TO 'BLOCKED';--> statement-breakpoint
ALTER TABLE "scope_authorisations" ADD CONSTRAINT "scope_authorisations_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "public"."tenants"("tenant_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "scope_authorisations" ADD CONSTRAINT "scope_authorisations_authoriser_fk" FOREIGN KEY ("tenant_id","authorised_by_user_id") REFERENCES "public"."users"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "scope_authorisations_target_idx" ON "scope_authorisations" USING btree ("tenant_id","target_type","target");--> statement-breakpoint
ALTER TABLE "collectors_registry" ADD CONSTRAINT "collectors_registry_blocked_never_enabled" CHECK (not "collectors_registry"."enabled" or "collectors_registry"."commercial_use" <> 'BLOCKED');